// The design fixtures (app/design/data/fixtures, real crawls: see its README), loaded lazily and brought up to the
// current contract. They're git-ignored and regenerated by `node app/design/data/extract/run-all.mjs`; when they're
// missing, every mock answer says so in plain words. This module is only ever imported with VITE_TRANSPORT=mock,
// so none of it reaches a real build.
import type {
  CheckGrouping,
  GridPage,
  IndexabilityReason,
  UrlOutcome,
  UrlRef,
  UrlRow,
  UrlSource,
  UrlType,
} from '../grids';
import {
  LINK_KINDS,
  type HtmlSource,
  type LinkPosition,
  type LinkRow,
  type NotFetchedBecause,
  type UrlDetail,
} from '../inspector';
import type { Analysis, Check, Checks, CrawlListItem, CrawlStats, ProgressEvent, Severity } from '../types';
import type { LinkFacts } from './linkGrid';

const files = import.meta.glob<unknown>('/design/data/fixtures/**/*.json', { import: 'default' });

export type FixtureCrawl = 'garden' | 'synthetic';

export class MissingFixtureError extends Error {
  constructor(path: string) {
    super(`Missing fixture: ${path}`);
  }
}

export function hasFixtures(): boolean {
  return Object.keys(files).length > 0;
}

export async function fixture<T>(path: string): Promise<T> {
  const load = files[`/design/data/fixtures/${path}`];
  if (!load) throw new MissingFixtureError(path);
  return (await load()) as T;
}

export async function optionalFixture<T>(path: string): Promise<T | null> {
  return files[`/design/data/fixtures/${path}`] ? fixture<T>(path) : null;
}

// The fixtures were saved from the sidecar at e5223b6. These bring them up to the contract as it is now.

export function adaptCrawlItem(raw: Record<string, unknown>): CrawlListItem {
  const { urlCount, ...rest } = raw;
  return {
    ...(rest as unknown as CrawlListItem),
    fetchedUrlCount:
      typeof raw.fetchedUrlCount === 'number' ? raw.fetchedUrlCount : typeof urlCount === 'number' ? urlCount : 0,
    error: typeof raw.error === 'string' ? raw.error : null,
  };
}

export function adaptAnalysis(raw: Record<string, unknown>): Analysis {
  return {
    ...(raw as unknown as Analysis),
    outOfDate: typeof raw.outOfDate === 'boolean' ? raw.outOfDate : false,
    outOfDateReasons: Array.isArray(raw.outOfDateReasons) ? (raw.outOfDateReasons as Analysis['outOfDateReasons']) : [],
  };
}

export function adaptStats(raw: Record<string, unknown>): CrawlStats {
  return {
    ...(raw as unknown as CrawlStats),
    notCheckedCount: typeof raw.notCheckedCount === 'number' ? raw.notCheckedCount : 0,
  };
}

export type LiveSnapshot = Omit<ProgressEvent, 'crawlId' | 'status'> & { pages: number };

/**
 * A snapshot of the garden crawl's replay as E4's progress carries it. The fixture was made before E4: its status
 * classes count a firewall's block page under its status code, where E4 counts it as `blocked` (the crawl's two were
 * 403s), and it has no `other` class and no reasons for the URLs without a response (the crawl's were refused by
 * robots.txt).
 */
export function adaptSnapshot(raw: Record<string, unknown>): LiveSnapshot {
  const rate =
    typeof raw.urlsPerSecond === 'number'
      ? raw.urlsPerSecond
      : typeof raw.pagesPerSecond === 'number'
        ? raw.pagesPerSecond
        : 0;
  const number = (key: string) => (typeof raw[key] === 'number' ? raw[key] : 0);
  const classes = (raw.statusClasses ?? {}) as Record<string, unknown>;
  const classCount = (key: string) => (typeof classes[key] === 'number' ? classes[key] : 0);
  const statusCodes = { ...((raw.statusCodes ?? {}) as Record<string, number>) };
  const blocked = Math.min(number('blocked'), statusCodes['403'] ?? 0);
  if (blocked > 0) {
    const genuine = (statusCodes['403'] ?? 0) - blocked;
    if (genuine > 0) statusCodes['403'] = genuine;
    else delete statusCodes['403'];
  }
  const noResponse = classCount('noResponse');
  const robotsDisallowed = Math.min(number('robotsDisallowed'), noResponse);
  return {
    elapsedMs: number('elapsedMs'),
    discovered: number('discovered'),
    queued: number('queued'),
    inFlight: number('inFlight'),
    fetched: number('fetched'),
    htmlPages: number('htmlPages'),
    redirects: number('redirects'),
    errors: number('errors'),
    blocked: number('blocked'),
    robotsDisallowed: number('robotsDisallowed'),
    skipped: number('skipped'),
    bytesDownloaded: number('bytesDownloaded'),
    urlsPerSecond: rate,
    pages: number('pages'),
    statusClasses: {
      '2xx': classCount('2xx'),
      '3xx': classCount('3xx'),
      '4xx': classCount('4xx') - blocked,
      '5xx': classCount('5xx'),
      other: classCount('other'),
      noResponse,
      blocked,
    },
    statusCodes,
    noResponse: {
      robotsDisallowed,
      timeout: 0,
      networkError: noResponse - robotsDisallowed,
      notChecked: 0,
      processingError: 0,
    },
  };
}

/** The fixtures' content types as E3a's `type` column names them. */
const TYPES: Record<string, UrlType> = {
  html: 'page',
  image: 'image',
  javascript: 'script',
  css: 'stylesheet',
  font: 'font',
  video: 'media',
  audio: 'media',
  pdf: 'pdf',
};

/**
 * A row of the design fixtures' urls.json under E3a's column names. Every fixture row was fetched; the analysis's
 * columns (issues by severity) come from the row's own list of checks and the catalog's severities.
 */
export function adaptUrlRow(raw: Record<string, unknown>, severities: ReadonlyMap<string, string>): Required<UrlRow> {
  // The fixtures are the engine's own output: each field is taken as the row's type says.
  const value = (key: string) => (raw[key] ?? null) as never;
  const checks = Array.isArray(raw.issues) ? raw.issues.filter((id): id is string => typeof id === 'string') : [];
  const count = (severity: string) => checks.filter((id) => severities.get(id) === severity).length;
  const type = typeof raw.type === 'string' ? raw.type : null;
  return {
    id: typeof raw.id === 'number' ? raw.id : 0,
    url: typeof raw.url === 'string' ? raw.url : '',
    fetched: true,
    isInternal: value('isInternal'),
    source: value('source'),
    depth: value('depth'),
    type: type === null ? null : (TYPES[type] ?? 'other'),
    statusCode: value('statusCode'),
    statusClass: value('statusClass'),
    outcome: value('outcome'),
    redirectTarget: value('redirectUrl'),
    redirectTargetStatusCode: null,
    indexable: value('indexable'),
    indexability: value('indexabilityReason'),
    noindex: value('isNoindex'),
    nofollow: value('isNofollow'),
    metaRobots: Array.isArray(raw.robotsDirectives) ? raw.robotsDirectives.join(', ') || null : null,
    xRobotsTag: null,
    canonicalUrl: value('canonicalUrl'),
    contentType: value('contentType'),
    title: value('title'),
    description: value('metaDescription'),
    h1: value('h1'),
    h1Count: value('h1Count'),
    wordCount: value('wordCount'),
    outlinks: value('outlinks'),
    sizeBytes: value('sizeBytes'),
    responseMs: value('responseMs'),
    ttfbMs: value('ttfbMs'),
    titleLength: value('titleLength'),
    descriptionLength: value('metaDescriptionLength'),
    finalUrl: (raw.finalUrl ?? raw.url ?? null) as never,
    finalStatusCode: (raw.finalStatusCode ?? raw.statusCode ?? null) as never,
    inSitemap: value('inSitemap'),
    inlinks: value('inlinks'),
    // The fixtures count links, and the pages they're on, but not which were followed.
    followedInlinks: null,
    nofollowInlinks: null,
    linkingPages: value('uniqueInlinks'),
    issues: checks.length,
    errors: count('error'),
    warnings: count('warning'),
    notices: count('notice'),
    // The design fixtures were captured before the evidence columns: what they'd say isn't known.
    usedOn: null,
    pixelWidth: null,
    pixelHeight: null,
    fetchError: null,
    redirectChain: null,
    robotsRule: null,
    // Nor the widths in pixels, which came after them.
    titleWidth: null,
    descriptionWidth: null,
    titleInResults: null,
    descriptionInResults: null,
  };
}

export async function urlRows(crawl: FixtureCrawl): Promise<Required<UrlRow>[]> {
  const [file, catalog] = await Promise.all([
    fixture<{ rows: Record<string, unknown>[] }>(
      crawl === 'garden' ? 'garden/urls.json' : 'synthetic/urls-sample.json',
    ),
    fixture<Checks>('api/checks.json'),
  ]);
  const severities = new Map(catalog.checks.map((check) => [check.id, check.severity]));
  return file.rows.map((row) => adaptUrlRow(row, severities));
}

/**
 * How the catalog groups each check's issues (E3a's `grouping`): the fixtures' catalog is older than it. These are
 * the engine's for the checks the fixtures have issues of; any other groups by its detail.
 */
const GROUPINGS: Record<string, CheckGrouping> = {
  'broken-internal-links': 'relatedUrl',
  'canonicalised-page': 'relatedUrl',
  'description-duplicate': 'relatedUrl',
  'empty-anchor-text': 'relatedUrl',
  'image-too-large': 'relatedUrl',
  'title-duplicate': 'relatedUrl',
  'canonical-missing': 'none',
  'description-missing': 'none',
  'description-too-long': 'none',
  'h1-missing': 'none',
  'image-missing-dimensions': 'none',
  'low-word-count': 'none',
  'security-headers-missing': 'none',
  'sitemap-missing': 'none',
  'slow-response': 'none',
  'title-too-long': 'none',
  'title-too-short': 'none',
};

/** The catalog as the fixtures saved it: older than `grouping`, `why` and `learnMore`. */
export type SavedChecks = Omit<Checks, 'checks'> & {
  checks: (Omit<Check, 'grouping' | 'why' | 'learnMore'> & {
    grouping?: CheckGrouping;
    why?: string;
    learnMore?: string | null;
  })[];
};

export function adaptChecks(raw: SavedChecks): Checks {
  return {
    ...raw,
    checks: raw.checks.map((check) => ({
      ...check,
      grouping: check.grouping ?? GROUPINGS[check.id] ?? 'detail',
      why: check.why ?? '',
      learnMore: check.learnMore ?? null,
    })),
  };
}

/** The design fixtures' inspector, for the few URLs they hold it for: by URL id. */
export async function inspectorFixtures(): Promise<Map<number, Record<string, unknown>>> {
  const prefix = '/design/data/fixtures/garden/inspector/';
  const loaded = await Promise.all(
    Object.keys(files)
      .filter((path) => path.startsWith(prefix))
      .map((path) => fixture<Record<string, unknown>>(path.slice('/design/data/fixtures/'.length))),
  );
  const byId = new Map<number, Record<string, unknown>>();
  for (const raw of loaded) {
    const id = (raw.summary as { id?: unknown } | undefined)?.id;
    if (typeof id === 'number') byId.set(id, raw);
  }
  return byId;
}

type Raw = Record<string, unknown>;

const string = (value: unknown): string | null => (typeof value === 'string' ? value : null);
const number = (value: unknown): number | null => (typeof value === 'number' ? value : null);
const list = (value: unknown): Raw[] => (Array.isArray(value) ? (value as Raw[]) : []);

/** A stored enum this engine knows, or null: the fixture invents nothing for a value it doesn't hold. */
function oneOf<T extends string>(value: unknown, allowed: readonly T[]): T | null {
  return typeof value === 'string' && (allowed as readonly string[]).includes(value) ? (value as T) : null;
}

const SOURCES = ['seed', 'link', 'sitemap', 'siteVersion'] as const satisfies readonly UrlSource[];
const OUTCOMES = [
  'success',
  'redirect',
  'clientError',
  'serverError',
  'blocked',
  'robotsDisallowed',
  'timeout',
  'networkError',
  'processingError',
  'notChecked',
] as const satisfies readonly UrlOutcome[];
const FETCH_MODES = ['crawl', 'check'] as const;
const URL_STATES = ['queued', 'fetching', 'done', 'skipped'] as const;
const SKIPPED_BECAUSE = [
  'none',
  'noFollow',
  'notFollowedByOption',
  'resourcesDisabled',
  'externalsDisabled',
  'depthLimit',
  'urlLimit',
] as const satisfies readonly NotFetchedBecause[];
const POSITIONS = [
  'content',
  'navigation',
  'header',
  'footer',
  'sidebar',
  'head',
] as const satisfies readonly LinkPosition[];

/** A URL's id in the crawl from its text, when the crawl has it. */
type IdOf = (url: string) => number | null;

/**
 * One URL in full (E3a's inspector) from the design fixture for it. What the fixture doesn't hold is left as the
 * contract says for "not known" (null, or no entries), never invented.
 */
export function adaptInspector(raw: Raw, idOf: IdOf): UrlDetail {
  const summary = (raw.summary ?? {}) as Raw;
  const page = raw.page as Raw | null;
  const id = number(summary.id) ?? 0;
  const url = string(summary.url) ?? '';
  const statusCode = number(summary.statusCode);
  const ref = (text: unknown): UrlRef | null => {
    const target = string(text);
    const targetId = target === null ? null : idOf(target);
    return target === null || targetId === null ? null : { id: targetId, url: target };
  };
  const chain = list((raw.redirects as Raw | undefined)?.chain);
  const last = chain.at(-1);
  const reason = oneOf(summary.indexabilityReason, [
    'none',
    'noindex',
    'canonicalised',
    'redirected',
    'clientError',
    'serverError',
    'blockedByRobots',
    'blocked',
    'unreachable',
  ] as const satisfies readonly IndexabilityReason[]);
  const canonical = ref(summary.canonicalUrl);
  const canonicalUrl = string(summary.canonicalUrl);
  const length = (text: string, measured: unknown) => ({ text, length: number(measured) ?? text.length });
  const titles = list(page?.titles).length > 0 ? (page?.titles as string[]) : [];
  const descriptions = (page?.metaDescriptions as string[] | undefined) ?? [];
  const headings = list(page?.headings);
  return {
    id,
    url,
    isInternal: summary.isInternal === true,
    type: TYPES[string(summary.type) ?? ''] ?? 'other',
    discovery: {
      source: oneOf(summary.source, SOURCES),
      depth: number(summary.depth),
      foundOn: ref(summary.foundOn),
      foundVia: oneOf(summary.foundVia, LINK_KINDS),
      fetchMode: oneOf(summary.fetchMode, FETCH_MODES),
      state: oneOf(summary.state, URL_STATES),
      notFetchedBecause: oneOf(summary.notFetchedBecause, SKIPPED_BECAUSE),
    },
    response: {
      fetched: summary.fetched === false ? false : true,
      outcome: oneOf(summary.outcome, OUTCOMES),
      statusCode,
      contentType: string(summary.contentType),
      httpVersion: string(summary.httpVersion),
      crawledAt: string(summary.crawledAt) ?? '',
      ttfbMs: number(summary.ttfbMs),
      responseMs: number(summary.responseMs),
      sizeBytes: number(summary.sizeBytes),
      bodyBytes: number(summary.bodyBytes),
      blockReason: string(summary.blockReason),
      error: string(summary.error),
    },
    redirects: {
      hops: chain.slice(1).map((hop, index) => ({
        id: number(hop.id) ?? 0,
        url: string(hop.url) ?? '',
        statusCode: number(hop.statusCode),
        outcome: string(hop.outcome) as UrlOutcome | null,
        via: chain[index]?.redirectsVia === 'metaRefresh' ? 'metaRefresh' : 'http',
      })),
      final: last
        ? { id: number(last.id) ?? id, url: string(last.url) ?? url, statusCode: number(last.statusCode) }
        : { id, url, statusCode },
      loop: chain.some((hop) => hop.loop === true),
      tooLong: false,
    },
    indexability: {
      indexable: typeof summary.indexable === 'boolean' ? summary.indexable : null,
      reason,
      judgedBy: 'analysis',
      tests: [
        statusCode === null
          ? { test: 'answered', outcome: 'notChecked' }
          : { test: 'answered', outcome: statusCode >= 200 && statusCode < 300 ? 'pass' : 'fail', statusCode },
        { test: 'robotsTxt', outcome: reason === 'blockedByRobots' ? 'fail' : 'pass' },
        {
          test: 'noindex',
          outcome: summary.isNoindex === true ? 'fail' : 'pass',
          meta: summary.noindexSource === 'meta' || summary.noindexSource === 'both',
          header: summary.noindexSource === 'header' || summary.noindexSource === 'both',
        },
        {
          test: 'canonical',
          outcome: reason === 'canonicalised' ? 'fail' : 'pass',
          ...(canonical ? { canonical: { ...canonical, statusCode: null } } : {}),
          ...(canonicalUrl ? { canonicalUrl } : {}),
        },
      ],
    },
    content: page
      ? {
          titles: titles.map((text, index) => length(text, index === 0 ? summary.titleLength : undefined)),
          descriptions: descriptions.map((text, index) =>
            length(text, index === 0 ? summary.metaDescriptionLength : undefined),
          ),
          h1s: headings
            .filter((heading) => heading.level === 1)
            .map((heading) => length(String(heading.text), undefined)),
          headings: [1, 2, 3, 4, 5, 6].map((level) => headings.filter((heading) => heading.level === level).length),
          wordCount: number(page.wordCount) ?? number(summary.wordCount) ?? 0,
          language: string(page.language),
          charset: string(page.declaredCharset),
          robots: Array.isArray(summary.robotsDirectives) ? (summary.robotsDirectives as string[]) : [],
          metaRefresh: null,
          images: number(summary.imageCount) ?? 0,
          imagesMissingAlt: number(summary.imagesMissingAlt) ?? 0,
        }
      : null,
    limits: {
      titleMin: 30,
      titleMax: 60,
      descriptionMin: 70,
      descriptionMax: 155,
      minWords: 200,
      slowResponseMs: 1000,
      largePageBytes: 1_048_576,
      largeImageBytes: 204_800,
      imageAltMaxLength: 125,
      maxUrlLength: 115,
      fromAnalysis: false,
    },
    links: {
      inlinks: number(summary.inlinks) ?? 0,
      followedInlinks: number(summary.inlinks) ?? 0,
      nofollowInlinks: 0,
      linkingPages: number(summary.uniqueInlinks) ?? 0,
      outlinks: number(summary.outlinks),
      inSitemap: typeof summary.inSitemap === 'boolean' ? summary.inSitemap : null,
    },
    headers: list((raw.headers as Raw | undefined)?.rows).map((header) => ({
      name: String(header.name),
      value: String(header.value),
    })),
    structuredData: list(raw.structuredData).map((block) => ({
      valid: block.valid === true,
      types: Array.isArray(block.types) ? (block.types as string[]) : [],
      json: typeof block.json === 'string' ? block.json : JSON.stringify(block.json ?? null),
      error: string(block.error),
      truncated: block.truncated === true,
    })),
    hreflang: [],
    issues: list((raw.issues as Raw | undefined)?.rows).map((issue) => ({
      checkId: String(issue.checkId),
      severity: (string(issue.severity) ?? null) as Severity | null,
      detail: string(issue.detail),
      related: ref(issue.relatedUrl),
    })),
    namedBy: { total: number((raw.issuesNamingThisUrl as Raw | undefined)?.total) ?? 0, checks: [] },
    summary: { available: true, reason: null },
    source: { stored: (raw.source as Raw | undefined)?.stored === true },
  };
}

/** A URL's links one way, from its design fixture. */
export function adaptLinks(raw: Raw, direction: 'inlinks' | 'outlinks'): LinkRow[] {
  return list((raw[direction] as Raw | undefined)?.rows).map((row) => {
    const inbound = direction === 'inlinks';
    return {
      id: number(inbound ? row.fromId : row.toId) ?? 0,
      url: string(inbound ? row.fromUrl : row.toUrl) ?? '',
      kind: oneOf(row.kind, LINK_KINDS),
      text: string(row.anchorText),
      position: oneOf(row.position, POSITIONS),
      flags: Array.isArray(row.flags) ? (row.flags as LinkRow['flags']) : [],
      followed: row.kind === 'hyperlink' ? !(Array.isArray(row.flags) && row.flags.includes('noFollow')) : null,
      fragment: string(row.fragment),
      statusCode: number(inbound ? row.fromStatusCode : row.statusCode),
      indexable:
        typeof (inbound ? row.fromIndexable : row.indexable) === 'boolean'
          ? ((inbound ? row.fromIndexable : row.indexable) as boolean)
          : null,
      fetched: inbound ? true : row.fetched === true,
    };
  });
}

/** The stored HTML from a URL's design fixture: null when the fixture doesn't hold it. */
export function adaptSource(raw: Raw): HtmlSource | null {
  const source = (raw.source ?? {}) as Raw;
  const summary = (raw.summary ?? {}) as Raw;
  if (source.stored !== true) return { stored: false, reason: summary.isPage === true ? 'notStored' : 'notPage' };
  return typeof source.html === 'string'
    ? {
        stored: true,
        html: source.html,
        bytes: source.bytes === null ? null : (number(source.bytes) ?? source.html.length),
        truncated: source.truncated === true,
      }
    : null;
}

export type { GridPage };

// ------------------------------------------------------------------------------------------------------ Links (E3b)

/**
 * The links the inspector fixtures hold, each once, for the mock's links grid: every fixture URL's outlinks, and the
 * inlinks to it from other pages, a page's links together in the order the fixtures have them. Real links of the
 * garden crawl, though only the few hundred around the URLs the fixtures cover.
 */
export async function linkFacts(): Promise<LinkFacts[]> {
  const byUrl = await inspectorFixtures();
  const seen = new Set<string>();
  const found: (LinkFacts & { order: number })[] = [];
  const add = (fromId: number | null, toId: number | null, row: Raw) => {
    if (fromId === null || toId === null) return;
    const flags = Array.isArray(row.flags) ? (row.flags as unknown[]) : [];
    const link: LinkFacts = {
      fromId,
      toId,
      kind: oneOf(row.kind, LINK_KINDS),
      text: string(row.anchorText),
      position: oneOf(row.position, POSITIONS),
      noFollow: flags.includes('noFollow'),
      sponsored: flags.includes('sponsored'),
      ugc: flags.includes('ugc'),
      imageLink: flags.includes('imageLink'),
      fragment: string(row.fragment),
    };
    const key = JSON.stringify(link);
    if (seen.has(key)) return;
    seen.add(key);
    found.push({ ...link, order: found.length });
  };
  for (const [urlId, raw] of [...byUrl.entries()].sort(([a], [b]) => a - b)) {
    for (const row of list((raw.outlinks as Raw | undefined)?.rows)) add(urlId, number(row.toId), row);
    for (const row of list((raw.inlinks as Raw | undefined)?.rows)) add(number(row.fromId), urlId, row);
  }
  return found.sort((a, b) => a.fromId - b.fromId || a.order - b.order).map(({ order: _order, ...link }) => link);
}
